#!/usr/bin/env python3
"""Writes results/v7/BENCH_V7.md and results/v7/PRACTICAL_V7.md from
results/v7/bench_v7.json, results/v7/practical_v7.json and the V6 json files.
Every number in the two markdown files is read from those json files here;
nothing is typed by hand."""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(os.path.dirname(HERE))
OUT = os.path.join(ROOT, "results", "v7")
BJ = json.load(open(os.path.join(OUT, "bench_v7.json")))
PJ = json.load(open(os.path.join(OUT, "practical_v7.json")))
B6 = json.load(open(os.path.join(ROOT, "results", "v6", "bench_v6.json")))
P6 = json.load(open(os.path.join(ROOT, "results", "v6", "practical_v6.json")))
WOUND = ["medetec", "co2wounds", "fuseg", "azh"]
SETS = WOUND + ["azh_train_slice"]
NICE = {"medetec": "Medetec", "co2wounds": "CO2Wounds-V2", "fuseg": "FUSeg", "azh": "AZH",
        "azh_train_slice": "control (azh_train_slice)", "mean": "mean of 4"}
MB = "method bootstrap, B = 2,000, default_rng(0)"
HB = "hierarchical bootstrap, B = 2,000, default_rng(1)"
DB = "data-only bootstrap, B = 2,000, default_rng(2)"
UB = "unit bootstrap, B = 2,000, default_rng([20261010, k]) with k the dataset index (the V6 draws)"


def f3(c):
    return f"{c['est']:+.3f} [{c['lo']:+.3f}, {c['hi']:+.3f}]"


def e3(c):
    return f"{c['est']:+.3f}"


def p3(x):
    return "n/a" if x is None else f"{x:.3f}"


def pc(x):
    return "n/a" if x is None else f"{100 * x:.1f}%"


def ci_pc(v):
    return f"[{100 * v[0]:.1f}%, {100 * v[1]:.1f}%]"


def short(n):
    return n.replace("@seeds", "").replace("_in", "")


def excl0(c):
    return c["lo"] > 0 or c["hi"] < 0


# ===================================================================== BENCH
def bench_md():
    R = BJ
    pools = R["pools"]
    rep = R["v6_reproduction"]
    L = ["# Synthetic benchmark analysis (V7)", "",
         "Script: `scripts/v7/bench_v7.py`. Numbers: `results/v7/bench_v7.json`. This file is generated by "
         "`scripts/v7/write_md_v7.py` from those numbers. V6 counterpart: `results/v6/BENCH_V6.md`.", "",
         "## Reproduction checks", "",
         f"- V6 code path (K and M means from pools_v5, as V6): {rep['tt']['n_numeric_exact']} of {rep['tt']['n_numeric']} "
         f"numeric values in `bench_v6.json` reproduced bit for bit (sections rel, texture, matched, texture counts, "
         f"generator orderings, leave-one-out, mean Dice). No value differs.",
         f"- perimage_v7 route (K and M per-image data from the new loader, including the hierarchical and data-only "
         f"bootstraps): {rep['v7']['n_numeric_exact']} of {rep['v7']['n_numeric']} values bit for bit. The other "
         f"{rep['v7']['n_mismatched']} are all plain group mean Dice values in the mean Dice table and differ by at most "
         f"{rep['v7']['max_abs_diff']:.1e}. Reason: the new loader averages per-image columns, pools_v5 stored "
         "per-method means, so the floating-point sums run in a different order. Every rank-based number "
         "(agreements, intervals, orderings) is identical.",
         f"- Per-image means of the new loader against pools_v5: K {R['checks']['K_v7_per_image_means_vs_pools_v5']:.1e}, "
         f"M {R['checks']['M_v7_per_image_means_vs_pools_v5']:.1e} (max absolute difference over 4 wound and 21 synthetic sets).",
         f"- Seed-averaged synthetic columns against the mean of each seed model's mean read straight from the score "
         f"files: max difference {R['checks']['seedcol_synth_means_vs_raw_files']:.1e}. Every synthetic set has "
         f"{R['checks']['n_images_per_synth_set'][0]} images.",
         "- Independent implementation: an earlier V7 script (`scripts/v7_morning/bench_v7.py`, written against an older version "
         "of the loader) is still on disk with its output `results/v7_morning/bench_v7.json`. Its M19, U+M19 and single-seed "
         "groups Ms0, Ms1, Ms2 (= M19_s0, M19_s1, M19_s2 here) match this run exactly: "
         + "; ".join(f"{k} {v['n_numeric_exact']}/{v['n_numeric']} equal" for k, v in R["crosscheck_old_v7_implementation"].items()) + ".",
         "", "## Definitions", "",
         "- Agreement: Spearman correlation (average ranks for ties) of per-method mean Dice between two sets, over a method set.",
         "- bench(R): agreement of generator B at the given amplitude with wound reference R, averaged over synthetic seeds 2024, 7, 101.",
         "- other(R): mean agreement of the other three wound datasets with R. Averaged over the 4 references it equals the mean of the 6 wound pairs ('pairs6').",
         "- diff(R) = bench(R) - other(R). Positive means the synthetic benchmark ranks the methods more like R than the other clinical wound datasets do. The 'mean' row averages Medetec, CO2Wounds-V2, FUSeg, AZH.",
         "- Groups. U 18 untrained, F 14 trained from scratch on FUSeg, K 14 trained on Kvasir, M (V6) = 10 ImageNet-pretrained architectures, training seed 0, + nnU-Net. "
         "P10s = the same 10 architectures, each scored as the per-image mean over its training seeds 0, 1, 2. "
         "N8s = 8 new architectures (unet_r50, deeplabv3p_r50, upernet_convnext_t, unet_swin_t, segformer_mitb2, unet_effb3, fpn_regnety016, manet_r50), seed-averaged the same way. "
         "M11s = P10s + nnU-Net. M19 = P10s + N8s + nnU-Net. nnU-Net has one training.",
         "- Diverged trainings (no scores): manet_r18 seed 2, manet_r50 seeds 0 and 2. So manet_r18_in@seeds averages 2 seeds and manet_r50@seeds is a single model (seed 1).",
         "- Single-seed groups: P10_s0 (10 models, identical to M without nnU-Net), P10_s1 (10), P10_s2 (9), N8_s0 (7), N8_s1 (8), N8_s2 (7), and M19_sk = P10_sk + N8_sk + nnU-Net (18, 19, 17 methods).",
         "- U and F have no per-image synthetic scores, so their synthetic per-method means come from pools_v5 exactly as in V6; this is why only modern and K groups get the hierarchical bootstrap.",
         f"- Intervals: percentile 95%. {MB[0].upper() + MB[1:]}, a fresh generator per method set; methods resampled with replacement within each group, mixtures keep their composition. "
         f"{HB[0].upper() + HB[1:]}; methods within the group plus, independently per dataset, clinical units (Medetec photograph, AZH photograph, otherwise image) and synthetic images. "
         f"{DB[0].upper() + DB[1:]}; units and images only, methods fixed; context, not the primary interval. These are the V6 methods and seeds.",
         ""]

    # ---- headline
    L += ["## Headline: V6 next to V7 (generator B, amplitude 40, mean over the 4 wound references)", "",
          f"Each cell: estimate [95% interval], {MB}.", "",
          "| method set | n methods | bench | other (= mean of 6 wound pairs) | diff |", "|---|---|---|---|---|"]
    for p in ("U", "F", "K", "M", "M11s", "M19", "P10s", "N8s", "U+M", "U+M11s", "U+M19", "U+F+K+M", "U+F+K+M19"):
        d = R["rel"][p]["40"]
        tag = " (V6)" if p in ("U", "F", "K", "M", "U+M") else (" (V6 groups, not in V6 bench)" if p == "U+F+K+M" else "")
        L.append(f"| {p}{tag} | {pools[p]} | {f3(d['mean|bench'])} | {f3(d['mean|other'])} | {f3(d['mean|diff'])} |")
    L += ["", "Hierarchical intervals for the same quantities:", "",
          "| method set | bench (hier) | other (hier) | diff (hier) | diff (data-only) |", "|---|---|---|---|---|"]
    for g, src in (("M", "v6"), ("K", "v6"), ("M11s", "v7"), ("M19", "v7"), ("P10s", "v7"), ("N8s", "v7")):
        h = (R["v6"]["rel_hier"] if src == "v6" else R["rel_hier"])[g]["40"]
        d = (R["v6"]["rel_dataonly"] if src == "v6" else R["rel_dataonly"])[g]["40"]
        L.append(f"| {g}{' (V6)' if src == 'v6' else ''} | {f3(h['mean|bench'])} | {f3(h['mean|other'])} | {f3(h['mean|diff'])} | {f3(d['mean|diff'])} |")
    m6, m19, um6, um19 = (R["rel"][p]["40"] for p in ("M", "M19", "U+M", "U+M19"))
    L += ["", "In words:",
          f"- The V6 headline numbers are reproduced: U bench {e3(R['rel']['U']['40']['mean|bench'])}, M bench {e3(m6['mean|bench'])}, U+M bench {e3(um6['mean|bench'])}.",
          f"- Modern group. Averaging the ten V6 architectures over three training seeds (M11s) changes the benchmark agreement from {e3(m6['mean|bench'])} to {e3(R['rel']['M11s']['40']['mean|bench'])} "
          f"and raises the agreement among the wound datasets from {e3(m6['mean|other'])} to {e3(R['rel']['M11s']['40']['mean|other'])}. "
          f"Adding the 8 new architectures (M19) gives bench {e3(m19['mean|bench'])} and other {e3(m19['mean|other'])}, so diff {e3(m19['mean|diff'])}: "
          "the benchmark ranks the 19 modern methods about as well as one wound dataset ranks them for another, and both are weak. For M11s, M19, P10s and N8s the mean diff interval includes zero under both the method and the hierarchical bootstrap.",
          f"- The 8 new architectures alone (N8s) give bench {f3(R['rel']['N8s']['40']['mean|bench'])}: the benchmark does not rank them like the wound data at all, while the wound datasets agree among themselves at {e3(R['rel']['N8s']['40']['mean|other'])}. With 8 methods the intervals are very wide.",
          f"- Pooled with the untrained methods (where part of the agreement comes from the difficulty gap between the groups; see Limitations): U+M19 bench {e3(um19['mean|bench'])}, other {e3(um19['mean|other'])}, "
          f"diff {f3(um19['mean|diff'])} ({'excludes' if excl0(um19['mean|diff']) else 'includes'} zero). In V6, U+M diff was {f3(um6['mean|diff'])}. "
          f"With all 65 methods (U+F+K+M19) diff is {f3(R['rel']['U+F+K+M19']['40']['mean|diff'])}. In the pooled sets the benchmark is a slightly worse proxy than another wound dataset.",
          ""]

    # ---- seed effect
    se = R["seed_effect_amp40"]
    L += ["## Seed effect on the benchmark (amplitude 40)", "",
          f"Single-seed groups against seed-averaged groups. bench, other and diff are means over the 4 wound references; {MB}. "
          "'bench by reference' lists the point estimates for Medetec / CO2Wounds-V2 / FUSeg / AZH.", "",
          "| group | n | bench | other | diff | bench by reference |", "|---|---|---|---|---|---|"]
    for p in ("P10s", "P10_s0", "P10_s1", "P10_s2", "N8s", "N8_s0", "N8_s1", "N8_s2",
              "M19", "M19_s0", "M19_s1", "M19_s2", "M", "M11s"):
        v = se[p]
        L.append(f"| {p} | {v['n_methods']} | {f3(v['bench'])} | {f3(v['other'])} | {f3(v['diff'])} | "
                 + " / ".join(f"{v['bench_by_ref'][r]:+.2f}" for r in WOUND) + " |")
    L += ["",
          f"- Original ten architectures: single seeds give bench {se['_P10_single_seed_bench_range'][0]:+.3f} to {se['_P10_single_seed_bench_range'][1]:+.3f} "
          f"(mean {se['_P10_single_seed_bench_mean']:+.3f}); the seed-averaged P10s gives {se['P10s']['bench']['est']:+.3f}.",
          f"- New eight: single seeds {se['_N8_single_seed_bench_range'][0]:+.3f} to {se['_N8_single_seed_bench_range'][1]:+.3f} (mean {se['_N8_single_seed_bench_mean']:+.3f}); seed-averaged N8s {se['N8s']['bench']['est']:+.3f}.",
          f"- All 18 + nnU-Net: single seeds {se['_M19_single_seed_bench_range'][0]:+.3f} to {se['_M19_single_seed_bench_range'][1]:+.3f}; seed-averaged M19 {se['M19']['bench']['est']:+.3f}.",
          f"- The wound-to-wound agreement ('other') also moves with the training seed: P10 single seeds {se['P10_s0']['other']['est']:+.3f}, {se['P10_s1']['other']['est']:+.3f}, {se['P10_s2']['other']['est']:+.3f} (range {max(se[p]['other']['est'] for p in ('P10_s0','P10_s1','P10_s2')) - min(se[p]['other']['est'] for p in ('P10_s0','P10_s1','P10_s2')):.3f}, against {se['_P10_single_seed_bench_range'][1] - se['_P10_single_seed_bench_range'][0]:.3f} for bench); seed-averaged {se['P10s']['other']['est']:+.3f}.",
          f"- M (V6) and P10_s0 differ only by nnU-Net: adding nnU-Net moves bench from {se['P10_s0']['bench']['est']:+.3f} to {se['M']['bench']['est']:+.3f}.",
          "- For the original ten, per-reference values swing more than the means. For example the Medetec benchmark agreement is "
          + ", ".join(f"{se[p]['bench_by_ref']['medetec']:+.2f} ({p})" for p in ("P10_s0", "P10_s1", "P10_s2", "P10s")) + ".",
          "- Spread over the three synthetic seeds (training seeds fixed), mean over references, amplitude 40: "
          + "; ".join(f"{p} " + ", ".join(f"{R['bench40_per_synth_seed'][p][f'genB_amp40_s{s}|mean']['est']:+.3f}" for s in (2024, 7, 101))
                      for p in ("M", "M11s", "M19", "N8s")) + ".",
          ""]

    # ---- per reference tables
    for amp in ("40", "11"):
        L += [f"## Relative agreement per reference, amplitude {amp}", "",
              f"{MB[0].upper() + MB[1:]}.", "",
              "| set | ref | bench | other | diff |", "|---|---|---|---|---|"]
        for p in ("M11s", "M19", "P10s", "N8s", "U+M11s", "U+M19", "U+F+K+M", "U+F+K+M19"):
            d = R["rel"][p][amp]
            for r in WOUND + ["mean"]:
                L.append(f"| {p} | {r} | {f3(d[r + '|bench'])} | {f3(d[r + '|other'])} | {f3(d[r + '|diff'])} |")
        L += ["", f"Hierarchical and data-only intervals ({HB}; {DB}):", "",
              "| set | ref | bench (hier) | other (hier) | diff (hier) | diff (data-only) |", "|---|---|---|---|---|---|"]
        for g in ("M11s", "M19", "P10s", "N8s"):
            h, d = R["rel_hier"][g][amp], R["rel_dataonly"][g][amp]
            for r in WOUND + ["mean"]:
                L.append(f"| {g} | {r} | {f3(h[r + '|bench'])} | {f3(h[r + '|other'])} | {f3(h[r + '|diff'])} | {f3(d[r + '|diff'])} |")
        L += ["", "Per-reference diff intervals that exclude zero (method bootstrap): "
              + "; ".join(f"{p}: {', '.join(r for r in WOUND if excl0(R['rel'][p][amp][r + '|diff'])) or 'none'}"
                          for p in ("M11s", "M19", "P10s", "N8s", "U+M11s", "U+M19", "U+F+K+M", "U+F+K+M19")) + ".", ""]

    # ---- texture
    L += ["## Texture effect (amplitude 40 minus amplitude 11)", "",
          f"Mean over synthetic seeds of agreement at amplitude 40 minus the same at 11; {MB}.", "",
          "| set | " + " | ".join(WOUND) + " | mean | V6 counterpart, mean |", "|---" * 7 + "|"]
    v6c = {"M11s": "M", "M19": "M", "P10s": "M", "N8s": "M", "U+M11s": "U+M", "U+M19": "U+M", "U+F+K+M": None, "U+F+K+M19": None}
    for p, q in v6c.items():
        L.append(f"| {p} | " + " | ".join(f3(R["texture"][p][r]) for r in WOUND + ["mean"]) + " | "
                 + (f"{q} {f3(B6['texture'][q]['mean'])}" if q else "none") + " |")
    tc = R["texture_counts_v7family"]
    L += ["", f"- V7 family ({', '.join(tc['all_sets_per_dataset']['sets'])}): within-group per-dataset intervals excluding zero "
          f"{len(tc['within_group_per_dataset']['exclude_zero'])} of {tc['within_group_per_dataset']['total']} "
          f"({', '.join(tc['within_group_per_dataset']['exclude_zero']) or 'none'}); chance level {tc['within_group_per_dataset']['expected_by_chance_if_all_null']:.1f}. "
          f"All 7 sets: {len(tc['all_sets_per_dataset']['exclude_zero'])} of {tc['all_sets_per_dataset']['total']} "
          f"({', '.join(tc['all_sets_per_dataset']['exclude_zero'])}). 'mean' intervals excluding zero: {', '.join(tc['mean_row_exclude_zero'])}. "
          f"V6: {len(B6['texture_counts']['within_group_per_dataset']['exclude_zero'])} of 16 and {len(B6['texture_counts']['all_sets_per_dataset']['exclude_zero'])} of 28.",
          f"- N8s mean texture effect: upper interval bound is {R['texture']['N8s']['mean']['hi']:.1e}, i.e. zero to floating-point precision; it counts as including zero.",
          f"- Texture effect, mean, {HB}: " + "; ".join(f"{g} {f3(R['texture_hier'][g]['mean'])}" for g in R["texture_hier"])
          + f". V6 M: {f3(B6['texture_hier']['M']['mean'])}.",
          "- Within modern groups the texture effect is now slightly negative (amplitude 11 ranks modern methods a little more like the wound data than amplitude 40), "
          "but every modern interval includes zero, per reference and for the mean. In the pooled U+modern sets it is positive, as in V6, and for U+M19 every reference interval excludes zero.", ""]

    # ---- generator families
    L += ["## Generator families (non-reducibility sets)", "",
          f"Agreement with the mean of all 4 wound datasets; seed-mean over synthetic seeds; B0 - C34 with {MB}.", "",
          "| set | nrA | nrB0 | nrC0 | nrC34 | B0 - C34 seed mean [95%] |", "|---|---|---|---|---|---|"]
    for p in ("M", "M11s", "M19", "P10s", "N8s", "U+M", "U+M11s", "U+M19", "U+F+K+M19"):
        m = R["matched"][p]
        L.append(f"| {p} | " + " | ".join(f"{m[f'{g}_seedmean|mean4']['est']:+.3f}" for g in ("nrA", "nrB0", "nrC0", "nrC34"))
                 + f" | {f3(m['B0-C34_seedmean|mean4'])} |")
    for t, lab in (("M+A", "Medetec and AZH"), ("M+C", "Medetec and CO2Wounds-V2"), ("mean4", "all 4 wound datasets")):
        o = R["gen_order_v7family"][t]; o6 = B6["gen_order"][t]
        L += ["", f"Agreement with {lab}, seed-mean orderings in the V7 family: "
              + "; ".join(f"{p}: {o[p]['seedmean']}" for p in R["texture_counts_v7family"]["all_sets_per_dataset"]["sets"])
              + f". Same in all 7 sets: {'yes' if o['_stable_seedmean_ordering_across_pools'] else 'no'} (V6: {'yes' if o6['_stable_seedmean_ordering_across_pools'] else 'no'}). "
              f"V6 M ordering: {o6['M']['seedmean']}. Pairwise (first beats second, of 21 set x seed cells; of 7 seed means): "
              + "; ".join(f"{k} {v['pool_seed_cells']}, {v['pools_seedmean']}" for k, v in o["_pairwise"].items()) + "."]
    L.append("")

    # ---- LOMO
    L += ["## Leave-one-method-out, M19 (amplitude 40, means over references)", "",
          "| dropped | bench | 6-pair wound | diff |", "|---|---|---|---|"]
    for n, v in R["lomo"]["M19"].items():
        L.append(f"| {n} | {v['bench40_mean']:+.3f} | {v['pairs6']:+.3f} | {v['rel40_mean']:+.3f} |")
    lo = R["lomo"]["M19"]
    # wording below: unet_effb3 is the drop that raises bench most and has the largest synthetic seed range
    assert max((k for k in lo if k != "_all"), key=lambda k: lo[k]["bench40_mean"]) == "unet_effb3@seeds"
    sr = PJ["synthetic_dice_by_training_seed"]["amp40"]
    assert max(sr, key=lambda a: sr[a]["range"]) == "unet_effb3"
    vals = [v["bench40_mean"] for k, v in lo.items() if k != "_all"]
    L += ["", f"- Dropping one method moves M19 bench between {min(vals):+.3f} and {max(vals):+.3f} (all methods: {lo['_all']['bench40_mean']:+.3f}). "
          f"Dropping nnU-Net: {lo['nnunet_2d']['bench40_mean']:+.3f}; dropping unet_effb3: {lo['unet_effb3@seeds']['bench40_mean']:+.3f} (diff {lo['unet_effb3@seeds']['rel40_mean']:+.3f}). "
          "unet_effb3 is the single method that lowers M19 benchmark agreement most; its synthetic Dice also varies most with its training seed (PRACTICAL_V7.md, section 3). V6 M range: "
          f"{min(v['bench40_mean'] for k, v in B6['lomo_M'].items() if k != '_all'):+.3f} to {max(v['bench40_mean'] for k, v in B6['lomo_M'].items() if k != '_all'):+.3f}.", ""]

    # ---- mean dice
    md = R["mean_dice"]
    cols = ("U", "F", "K", "M", "M11s", "M19", "N8s", "M19_s0", "M19_s1", "M19_s2")
    L += ["## Mean Dice by group", "", "Group mean of per-method mean Dice. U and F synthetic values from pools_v5.", "",
          "| set | " + " | ".join(cols) + " |", "|---" * (len(cols) + 1) + "|"]
    rows = WOUND + [f"genB_amp{a}_seedmean" for a in (11, 28, 40)] + [f"{g}_seedmean" for g in ("nrA", "nrB0", "nrC0", "nrC34")]
    for s in rows:
        L.append(f"| {s} | " + " | ".join(f"{md[g][s]:.3f}" for g in cols) + " |")
    L += ["", f"- The floor effect on nrA persists: M19 mean Dice {md['M19']['nrA_seedmean']:.3f}, N8s {md['N8s']['nrA_seedmean']:.3f}.", ""]

    # ---- what changed
    L += ["## What changed from V6", "",
          "- Loader: `perimage_v7` instead of `perimage_v6` (adds seeds 1 and 2 of the ten original architectures, 8 new architectures with seeds 0 to 2, per-image seed averages, and `load_synth` for synthetic per-image scores).",
          "- New method sets M11s, M19, P10s, N8s, U+M11s, U+M19, U+F+K+M, U+F+K+M19, and single-seed groups P10_s0..2, N8_s0..2, M19_s0..2. Hierarchical and data-only bootstraps for M11s, M19, P10s, N8s.",
          "- New outputs: agreement per synthetic seed (`bench40_per_synth_seed`), seed-effect summary, generator orderings and texture counts for the V7 family (U, F, K, M19, U+F, U+K, U+M19), leave-one-out for M19 and M11s.",
          "- Unchanged: all definitions, U, F, K numbers, bootstrap designs, draws and RNG seeds. The V6 block is re-run and stored under `v6` in the json.",
          f"- Main shift: the modern group's apparent advantage of the benchmark over another wound dataset (V6 M diff {e3(m6['mean|diff'])}) disappears (M19 diff {e3(m19['mean|diff'])}). "
          f"Seed averaging of the ten V6 architectures alone moves it to {e3(R['rel']['M11s']['40']['mean|diff'])} (M11s); adding the eight new architectures moves it to {e3(m19['mean|diff'])}. "
          "V6 never claimed the M diff was distinguishable from zero, and that remains true.",
          "",
          "## Limitations", "",
          "- Seed averages use 3 seeds except manet_r18 (2) and manet_r50 (1, a single model). The diverged runs are missing, not imputed.",
          "- nnU-Net has one training, so its seed noise is not averaged out and it appears unchanged in every single-seed group.",
          "- The P10 and N8 single-seed groups have 7 to 10 methods, so their method-bootstrap intervals are wide; the differences between training seeds lie inside them.",
          "- U and F synthetic means come from earlier per-method files (pools_v5), so mixtures with U or F get only the method bootstrap.",
          "- The four per-reference diffs share data and are not independent; the pooled sets mix within-group ordering with between-group difficulty offsets (as in V6).",
          "- Data-only intervals are context only: resampling images pulls Spearman toward zero, so they sit asymmetrically around the estimate.",
          ""]
    txt = "\n".join(L)
    assert "\u2014" not in txt and "\u2013" not in txt
    open(os.path.join(OUT, "BENCH_V7.md"), "w").write(txt)


# ================================================================= PRACTICAL
def practical_md():
    R = PJ
    S = R["selection"]
    rep = R["v6_reproduction"]
    m6 = P6["miss"]["0.1"]["table"]
    mi = R["miss"]["0.1"]
    L = ["# Practical consequences for choosing a model (V7)", "",
         "Script: `scripts/v7/practical_v7.py`. Numbers: `results/v7/practical_v7.json`. Generated by `scripts/v7/write_md_v7.py`. "
         "V6 counterpart: `results/v6/PRACTICAL_V6.md`.", "",
         "## Reproduction checks", "",
         f"- The V6 script, ported to the new loader and run with the V6 group M, reproduces `practical_v6.json` exactly: "
         f"{rep['n_equal']} of {rep['n_common']} values identical, none missing, none extra (all sections, including the AZH image-size, padding and SIFT checks and SAM).",
         f"- Seed-0 checks inside V7: the mean miss rate of the 10 seed-0 models (P10_s0) and nnU-Net's miss rate equal the V6 values on every set and threshold.",
         f"- V6 computed the random-choice mean ({P6['selection']['random_mean_over_B']}) as the mean of 4 already-rounded values; V7 averages unrounded values ({S['M']['random_mean_over_B']:.5f} for M). Both are {P6['selection']['random_mean_over_B']:.3f} at 3 decimals. V7 stores unrounded values for all new quantities so that the report rounds only once.",
         f"- An earlier V7 implementation (`results/v7_morning/practical_v7.json`, independent code written against an older loader) agrees at 4 decimals on {sum(1 for k, v in R['crosscheck_old_v7'].items() if not k.startswith('_') and v)} of {sum(1 for k in R['crosscheck_old_v7'] if not k.startswith('_'))} checked blocks: the M19 loss matrix, off-diagonal, random and minimax values, the amp 11 and amp 40 synthetic picks and losses, the single-seed sets M19_s0..2, and the 18-architecture miss rates with intervals at all 3 thresholds and 5 sets.",
         "", "## Definitions", "",
         "- Per-image Dice from `perimage_v7.load` (V6 exclusions). Empty reference: Dice 1 if the prediction is empty, else 0. Mean Dice over all kept images.",
         "- Candidate sets. M (V6): 10 pretrained architectures at training seed 0 + nnU-Net. M11s: the same 10 architectures, per-image Dice averaged over training seeds, + nnU-Net. "
         "M19: M11s + 8 new architectures (seed-averaged). N8s, P10s: the 8 new / 10 original architectures alone. "
         "M19_s0, M19_s1, M19_s2: every architecture that has that training seed, as that single model, + nnU-Net (18, 19, 17 candidates).",
         "- Selection loss A to B: best mean Dice on B minus the mean Dice on B of the candidate ranked first on A. Random choice: mean over candidates of (best on B minus candidate on B).",
         "- Synthetic chooser: generator B at amplitude 11, 28 or 40; mean Dice over the 45 images of each synthetic seed, then mean over seeds 2024, 7, 101.",
         "- Within 0.01 / 0.02 of the best: selection loss <= 0.01 / 0.02 Dice (unrounded).",
         "- Miss: non-empty reference and Dice < 0.1. Miss rate = misses / non-empty images. Computed for each individual trained model; an architecture's miss rate is the mean over its training seeds (min and max shown). "
         "A seed-averaged per-image Dice is not used for misses because it is not the output of any model.",
         f"- Intervals: {UB}. Every image of a drawn unit counts once per draw of that unit; the same draws for all models of a dataset. "
         "Interval of a group or architecture mean: the same mean taken inside each draw. Units are photographs for Medetec and AZH, images otherwise. These intervals reflect image sampling only, with the models fixed.",
         "- V6 reported no bootstrap interval for miss rates. The figure '23.6% to 38.6%' in V6 is the range over the 10 pretrained models, not an interval. The V6-model intervals below use the V6 draws.",
         ""]

    # ---- headline
    a40 = lambda k: S[k]["synthetic"]["amp40"]
    g = mi["azh"]["groups"]
    L += ["## Headline: V6 next to V7", "",
          "| quantity | V6 (M, 11) | V7 (M19, 19) |", "|---|---|---|",
          f"| Selection loss, choose on one wound set, deploy on another (mean of 12 ordered pairs) | {P6['selection']['offdiag_mean']:.3f} | {S['M19']['offdiag_mean']:.3f} |",
          f"| Random-choice expected loss (mean of 4 wound sets) | {P6['selection']['random_mean_over_B']:.3f} | {S['M19']['random_mean_over_B']:.3f} |",
          f"| Synthetic pick (amp 40), mean loss over 4 wound sets | {P6['selection']['synthetic']['amp40']['chosen']}, {P6['selection']['synthetic']['amp40']['mean_loss']:.3f} | {a40('M19')['chosen']}, {a40('M19')['mean_loss']:.3f} |",
          f"| Synthetic pick within 0.01 / 0.02 of the best (of 4 wound sets, amp 40) | {a40('M')['n_within_0.01']} / {a40('M')['n_within_0.02']} | {a40('M19')['n_within_0.01']} / {a40('M19')['n_within_0.02']} |",
          f"| Minimax candidate (smallest maximum gap from the best) | {P6['selection']['minimax_model']}, {P6['selection']['minimax_gap']:.3f} | {short(S['M19']['minimax_model'])}, {S['M19']['minimax_gap']:.3f} |",
          f"| nnU-Net maximum gap from the best | {P6['selection']['max_gap_from_best']['nnunet_2d']:.3f} | {S['M19']['max_gap_from_best']['nnunet_2d']:.3f} |",
          f"| Spearman of mean Dice, mean of 6 wound pairs | {P6['spearman_mean_dice']['mean']:.3f} | {S['M19']['spearman_mean_dice_6pairs']:.3f} |",
          f"| AZH miss rate, pretrained architectures [95% {('unit bootstrap')}] | {pc(g['P10_s0_modelmean']['est'])} {ci_pc(g['P10_s0_modelmean']['ci'])} (10 models) | {pc(g['P18_archmean']['est'])} {ci_pc(g['P18_archmean']['ci'])} (18 architectures) |",
          f"| AZH miss rate, nnU-Net | {pc(mi['azh']['per_model']['nnunet_2d']['miss_rate'])} {ci_pc(mi['azh']['per_model']['nnunet_2d']['ci'])} | same model |",
          f"| FUSeg miss rate, pretrained | {pc(mi['fuseg']['groups']['P10_s0_modelmean']['est'])} {ci_pc(mi['fuseg']['groups']['P10_s0_modelmean']['ci'])} | {pc(mi['fuseg']['groups']['P18_archmean']['est'])} {ci_pc(mi['fuseg']['groups']['P18_archmean']['ci'])} |",
          f"| AZH black-pixel share, mean over non-empty images (all 150 kept images) | {P6['azh_explanation']['azh']['black_pixel_share']['mean_all_nonempty']:.3f} | {R['padding']['azh']['black_share_mean_nonempty']:.3f} ({R['padding']['azh']['black_share_mean_all_kept']:.3f}) |",
          f"| FUSeg black-pixel share, non-empty (all kept) | {P6['azh_explanation']['fuseg']['black_pixel_share']['mean_all_nonempty']:.3f} | {R['padding']['fuseg']['black_share_mean_nonempty']:.3f} ({R['padding']['fuseg']['black_share_mean_all_kept']:.3f}) |",
          "", "Black-pixel share = share of pixels with every channel <= 8 in the kit reference image. V6 reports it over non-empty images only "
          f"(AZH {P6['azh_explanation']['azh']['black_pixel_share']['mean_all_nonempty']:.4f}, FUSeg {P6['azh_explanation']['fuseg']['black_pixel_share']['mean_all_nonempty']:.4f}). "
          f"Over all kept images it is AZH {R['padding']['azh']['black_share_mean_all_kept']:.4f}, FUSeg {R['padding']['fuseg']['black_share_mean_all_kept']:.4f}. "
          f"Medetec, not reported in V6: {R['padding']['medetec']['black_share_mean_all_kept']:.4f} (all 152 images are non-empty); CO2Wounds-V2 {R['padding']['co2wounds']['black_share_mean_all_kept']:.4f}.",
          ""]

    # ---- spread
    L += ["## 1 and 2. Spread within the candidate set", "",
          f"Top candidate by mean Dice, its 95% interval ({UB}), and how many others are indistinguishable from it (paired interval of top minus candidate has lower bound <= 0).", "",
          "| set | candidates | top | top mean [95%] | indistinguishable | top wins draws | best minus median | best minus worst (worst) |",
          "|---|---|---|---|---|---|---|---|"]
    for k in ("M19", "M11s", "N8s"):
        for s in SETS:
            v = R["spread"][k][s]
            L.append(f"| {NICE[s]} | {k} ({v['n_candidates']}) | {short(v['top'])} | {v['top_mean']:.3f} [{v['top_ci'][0]:.3f}, {v['top_ci'][1]:.3f}] | "
                     f"{v['n_indistinguishable_from_top']} of {v['n_candidates'] - 1} | {v['share_draws_top_is_top']:.2f} | {v['best_minus_median']:.3f} | {v['best_minus_worst']:.3f} ({short(v['worst'])}) |")
    L += ["", "Indistinguishable from the top in M19: "
          + "; ".join(f"{NICE[s]}: {', '.join(short(n) for n in R['spread']['M19'][s]['indistinguishable_from_top']) or 'none'}" for s in SETS) + ".",
          f"- On AZH, segformer_mitb2 ({R['spread']['M19']['azh']['means']['segformer_mitb2@seeds']:.3f}) is ahead of nnU-Net ({R['spread']['M19']['azh']['means']['nnunet_2d']:.3f}) and no other candidate is indistinguishable from it. In V6 nnU-Net was top on AZH.",
          ""]

    # ---- selection
    s19 = S["M19"]
    L += ["## 3. Selection with the 19 modern methods", "",
          "### Best method per dataset", "",
          "| dataset | M19 (seed-averaged) | M19_s0 | M19_s1 | M19_s2 | V6 (M) |", "|---|---|---|---|---|---|"]
    cb = R["clinical_best_by_training_seed"]
    for s in SETS:
        L.append(f"| {NICE[s]} | " + " | ".join(f"{short(cb[s][k]['model'])} {cb[s][k]['mean_dice']:.3f}" for k in ("M19", "M19_s0", "M19_s1", "M19_s2"))
                 + f" | {short(S['M']['best_per_dataset'][s]['model'])} {S['M']['best_per_dataset'][s]['mean_dice']:.3f} |")
    L += ["", "The best method changes with the training seed on Medetec, CO2Wounds-V2 and FUSeg. On AZH a segformer_mitb2 model is best for every training seed and after seed averaging.", "",
          "### Loss matrix, M19 (rows: chosen on; columns: deployed on)", "",
          "| chosen on (pick) | " + " | ".join(NICE[b] for b in WOUND) + " |", "|---" * 5 + "|"]
    for a in WOUND:
        L.append(f"| {NICE[a]} ({short(s19['chosen_on'][a])}) | " + " | ".join(f"{s19['matrix_rows_choose_on_cols_deploy_on'][a][b]:.3f}" for b in WOUND) + " |")
    L += ["", f"- Off-diagonal (12 pairs): mean {s19['offdiag_mean']:.3f}, range {s19['offdiag_min']:.3f} to {s19['offdiag_max']:.3f}.",
          "- Random choice, expected loss: " + ", ".join(f"{NICE[b]} {s19['random_choice_expected_loss'][b]:.3f}" for b in WOUND) + f" (mean {s19['random_mean_over_B']:.3f}).",
          f"- Control chooser (azh_train_slice) picks {short(s19['control_chooser'])}: losses " + ", ".join(f"{NICE[b]} {s19['control_chooser_loss'][b]:.3f}" for b in WOUND) + ".",
          ""]
    L += ["### Synthetic chooser, M19 (seed-averaged candidates)", "",
          "| amplitude | pick (synthetic Dice) | runner-up (synthetic Dice) | loss Medetec / CO2 / FUSeg / AZH | mean loss | within 0.01 | within 0.02 | pick per synthetic seed 2024 / 7 / 101 |",
          "|---|---|---|---|---|---|---|---|"]
    for amp in ("amp11", "amp28", "amp40"):
        v = s19["synthetic"][amp]
        L.append(f"| {amp[3:]} | {short(v['chosen'])} ({v['chosen_synth_dice']:.3f}) | {short(v['runner_up'])} ({v['runner_up_synth_dice']:.3f}) | "
                 + " / ".join(f"{v['loss'][b]:.3f}" for b in WOUND) + f" | {v['mean_loss']:.3f} | {v['n_within_0.01']} of 4 | {v['n_within_0.02']} of 4 | "
                 + " / ".join(short(v["chosen_per_synth_seed"][s]) for s in ("2024", "7", "101")) + " |")
    v = s19["synthetic"]["amp40"]
    L += ["", f"- Spearman between synthetic (amp 40) and clinical mean Dice over the 19 candidates: " + ", ".join(f"{NICE[b]} {v['spearman_with_wound'][b]:+.2f}" for b in WOUND) + ".",
          f"- For comparison, choosing on another wound dataset lands within 0.01 of the best in {s19['within']['0.01']['other_wound_chooser']} ordered pairs and within 0.02 in {s19['within']['0.02']['other_wound_chooser']}; "
          f"a random candidate is within 0.01 with probability {s19['within']['0.01']['random_share_mean']:.3f} and within 0.02 with probability {s19['within']['0.02']['random_share_mean']:.3f} (mean over the 4 wound datasets).",
          ""]
    L += ["### Does the synthetic pick change with the training seed?", "",
          "| candidate set | n | pick amp 11 | pick amp 28 | pick amp 40 | mean loss amp 40 | within 0.01 / 0.02 (amp 40, of 4) | off-diagonal wound chooser | random |",
          "|---|---|---|---|---|---|---|---|---|"]
    for k in ("M", "M11s", "M19", "M19_s0", "M19_s1", "M19_s2", "P10s", "N8s"):
        v = S[k]["synthetic"]
        L.append(f"| {k} | {S[k]['n_candidates']} | {short(v['amp11']['chosen'])} | {short(v['amp28']['chosen'])} | {short(v['amp40']['chosen'])} | {v['amp40']['mean_loss']:.3f} | "
                 f"{v['amp40']['n_within_0.01']} / {v['amp40']['n_within_0.02']} | {S[k]['offdiag_mean']:.3f} | {S[k]['random_mean_over_B']:.3f} |")
    L += ["", "How often the synthetic pick is within 0.01 / 0.02 Dice of the best, per wound dataset, counted over the 4 modern candidate sets (M19, M19_s0, M19_s1, M19_s2) x 3 amplitudes (11, 28, 40) = 12 cases:", "",
          "| dataset | within 0.01 | within 0.02 | V6 M (amp 11 and 40, 2 cases) within 0.01 / 0.02 |", "|---|---|---|---|"]
    for b in WOUND:
        c1 = sum(S[k]["synthetic"][a]["within_0.01"][b] for k in ("M19", "M19_s0", "M19_s1", "M19_s2") for a in ("amp11", "amp28", "amp40"))
        c2 = sum(S[k]["synthetic"][a]["within_0.02"][b] for k in ("M19", "M19_s0", "M19_s1", "M19_s2") for a in ("amp11", "amp28", "amp40"))
        v1 = sum(S["M"]["synthetic"][a]["within_0.01"][b] for a in ("amp11", "amp40"))
        v2 = sum(S["M"]["synthetic"][a]["within_0.02"][b] for a in ("amp11", "amp40"))
        L.append(f"| {NICE[b]} | {c1} of 12 | {c2} of 12 | {v1} / {v2} of 2 |")
    s0 = S["M19_s0"]["synthetic"]
    L += ["",
          f"- Yes. With seed-0 models (M19_s0) the synthetic benchmark picks unet_effb3_s0 at every amplitude (amp 40: {s0['amp40']['chosen_synth_dice']:.3f} against nnU-Net {s0['amp40']['runner_up_synth_dice']:.3f}); "
          f"its mean loss is {s0['amp40']['mean_loss']:.3f} and it is never within 0.02 of the best. With seeds 1 and 2, and after seed averaging, the pick is nnU-Net.",
          "- Per synthetic seed (amp 40), M19_s0 picks " + " / ".join(short(s0['amp40']['chosen_per_synth_seed'][s]) for s in ("2024", "7", "101"))
          + " for seeds 2024 / 7 / 101. So the pick depends on both the training seed and the synthetic seed when the top two are close.",
          f"- unet_effb3's synthetic Dice varies strongly with its training seed (amp 40: seed 0 {S['M19_s0']['synthetic']['amp40']['mean_dice']['unet_effb3_s0']:.3f}, seed 1 {S['M19_s1']['synthetic']['amp40']['mean_dice']['unet_effb3_s1']:.3f}, seed 2 {S['M19_s2']['synthetic']['amp40']['mean_dice']['unet_effb3_s2']:.3f}). "
          "Range of synthetic Dice (amp 40) over training seeds, per architecture with 2 or 3 seeds: "
          + ", ".join(f"{short(a)} {v['range']:.3f}" for a, v in sorted(R['synthetic_dice_by_training_seed']['amp40'].items(), key=lambda kv: -kv[1]['range']) if v['n_seeds'] > 1)
          + f". For comparison, the 19 seed-averaged M19 candidates span {min(S['M19']['synthetic']['amp40']['mean_dice'].values()):.3f} to {max(S['M19']['synthetic']['amp40']['mean_dice'].values()):.3f} on amp 40. "
          "Training-seed noise on the synthetic benchmark is of the same order as the differences between architectures.",
          f"- Among the 8 new architectures alone the synthetic pick is unet_effb3 (mean loss {S['N8s']['synthetic']['amp40']['mean_loss']:.3f}, within 0.02 on 0 of 4), worse than random ({S['N8s']['random_mean_over_B']:.3f}).",
          f"- Among the 10 original architectures alone (P10s) the amp 40 pick is segformer_mitb0 (mean loss {S['P10s']['synthetic']['amp40']['mean_loss']:.3f}); per synthetic seed it alternates with unet_mbv2.",
          "- Synthetic-pick loss per wound dataset, amp 40: " + "; ".join(f"{k}: " + " / ".join(f"{S[k]['synthetic']['amp40']['loss'][b]:.3f}" for b in WOUND) for k in ("M19", "M19_s0", "M19_s1", "M19_s2")) + " (Medetec / CO2 / FUSeg / AZH).",
          f"- nnU-Net's maximum gap from the best grows from {S['M']['max_gap_from_best']['nnunet_2d']:.3f} (V6, on FUSeg) to {S['M19']['max_gap_from_best']['nnunet_2d']:.3f} in M19, now on AZH, because segformer_mitb2 beats it there.",
          ""]

    # ---- misses
    L += ["## 4. Misses (t = 0.1) per architecture", "",
          f"Miss rate = share of non-empty reference images with Dice < 0.1. Per architecture: mean over its training seeds, min to max over seeds, and the 95% interval of the seed mean ({UB}). "
          f"AZH: {mi['azh']['n_nonempty']} non-empty images in {mi['azh']['n_units_nonempty']} photographs; FUSeg: {mi['fuseg']['n_nonempty']} images; control: {mi['azh_train_slice']['n_nonempty']} images in {mi['azh_train_slice']['n_units_nonempty']} photographs.", "",
          "| architecture | seeds | AZH mean (min to max) [95%] | FUSeg mean (min to max) | control mean (min to max) | Medetec mean | CO2Wounds mean |",
          "|---|---|---|---|---|---|---|"]
    ARCHS = list(mi["azh"]["per_architecture"])
    for a in ARCHS:
        z = {s: mi[s]["per_architecture"][a] for s in SETS}
        new = "" if a == "nnunet_2d" or a.endswith("_in") else " (new)"
        L.append(f"| {short(a)}{new} | {z['azh']['n_seeds']} | {pc(z['azh']['mean'])} ({pc(z['azh']['min'])} to {pc(z['azh']['max'])}) {ci_pc(z['azh']['ci_of_seed_mean'])} | "
                 f"{pc(z['fuseg']['mean'])} ({pc(z['fuseg']['min'])} to {pc(z['fuseg']['max'])}) | {pc(z['azh_train_slice']['mean'])} ({pc(z['azh_train_slice']['min'])} to {pc(z['azh_train_slice']['max'])}) | "
                 f"{pc(z['medetec']['mean'])} | {pc(z['co2wounds']['mean'])} |")
    L += ["", "Group summaries (equal weight per architecture; interval from the same draws; difference to nnU-Net paired):", "",
          "| group | dataset | mean miss [95%] | minus nnU-Net [95%] | range of architecture means | range of single models |", "|---|---|---|---|---|---|"]
    for s in ("azh", "fuseg", "azh_train_slice"):
        for gname, lab in (("P10_archmean", "original 10 (all seeds)"), ("N8_archmean", "new 8 (all seeds)"), ("P18_archmean", "all 18")):
            v = mi[s]["groups"][gname]
            L.append(f"| {lab} | {NICE[s]} | {pc(v['est'])} {ci_pc(v['ci'])} | {pc(v['minus_nnunet'])} {ci_pc(v['minus_nnunet_ci'])} | "
                     f"{pc(v['arch_mean_range'][0])} to {pc(v['arch_mean_range'][1])} | {pc(v['single_model_range'][0])} to {pc(v['single_model_range'][1])} |")
        nn = mi[s]["per_model"]["nnunet_2d"]
        L.append(f"| nnU-Net | {NICE[s]} | {pc(nn['miss_rate'])} {ci_pc(nn['ci'])} | | | |")
    L += ["", "Per training seed (mean over the models of that seed):", "",
          "| dataset | P10 s0 (V6) | P10 s1 | P10 s2 | N8 s0 | N8 s1 | N8 s2 |", "|---|---|---|---|---|---|---|"]
    for s in ("azh", "fuseg", "azh_train_slice"):
        gg = mi[s]["groups"]
        L.append(f"| {NICE[s]} | " + " | ".join(f"{pc(gg[k]['est'])} {ci_pc(gg[k]['ci'])}" for k in
                                                 ("P10_s0_modelmean", "P10_s1_modelmean", "P10_s2_modelmean", "N8_s0_modelmean", "N8_s1_modelmean", "N8_s2_modelmean")) + " |")
    pa = mi["azh"]["per_architecture"]
    newa = [a for a in ARCHS if not a.endswith("_in") and a != "nnunet_2d"]
    lowest = sorted(newa, key=lambda a: pa[a]["mean"])
    # wording below names these four and says they are below every original architecture
    assert lowest[:4] == ["segformer_mitb2", "fpn_regnety016", "upernet_convnext_t", "unet_swin_t"], lowest
    assert max(pa[a]["mean"] for a in lowest[:4]) < min(pa[a]["mean"] for a in ARCHS if a.endswith("_in"))
    assert pa["segformer_mitb2"]["ci_of_seed_mean"][0] > mi["azh"]["per_model"]["nnunet_2d"]["ci"][1]
    rest4 = ", ".join(f"{short(a)} {pc(pa[a]['mean'])}" for a in lowest[4:])
    L += ["",
          f"- V6 check: the 10 seed-0 models give {pc(mi['azh']['groups']['P10_s0_modelmean']['est'])} on AZH (V6 {pc(m6['azh']['_pretrained10_mean_miss'])}), single-model range "
          f"{pc(mi['azh']['groups']['P10_s0_modelmean']['range'][0])} to {pc(mi['azh']['groups']['P10_s0_modelmean']['range'][1])} (the V6 '23.6% to 38.6%'); nnU-Net {pc(mi['azh']['per_model']['nnunet_2d']['miss_rate'])}; FUSeg {pc(mi['fuseg']['groups']['P10_s0_modelmean']['est'])}.",
          f"- The new architectures also miss many AZH wounds. Their architecture means run from {pc(pa[lowest[0]]['mean'])} ({short(lowest[0])}) to {pc(pa[lowest[-1]]['mean'])} ({short(lowest[-1])}), "
          f"group mean {pc(mi['azh']['groups']['N8_archmean']['est'])} against {pc(mi['azh']['groups']['P10_archmean']['est'])} for the original ten. "
          f"Every one of the 18 pretrained architectures misses far more than nnU-Net ({pc(mi['azh']['per_model']['nnunet_2d']['miss_rate'])}); the lowest single pretrained model is at {pc(mi['azh']['groups']['P18_archmean']['single_model_range'][0])}.",
          "- Ordered by AZH miss rate, new architectures: " + ", ".join(f"{short(a)} {pc(pa[a]['mean'])}" for a in lowest) + ".",
          f"- The four lowest new architectures (SegFormer-B2, FPN RegNetY-016, UPerNet ConvNeXt-T, U-Net Swin-T) miss less than the original ten; the ResNet-50 and EfficientNet-B3 models ({rest4}) are at the level of the original ten. "
          f"Even the best, segformer_mitb2, misses {pa['segformer_mitb2']['mean'] / mi['azh']['per_model']['nnunet_2d']['miss_rate']:.1f} times as often as nnU-Net, and its interval {ci_pc(pa['segformer_mitb2']['ci_of_seed_mean'])} does not overlap nnU-Net's {ci_pc(mi['azh']['per_model']['nnunet_2d']['ci'])}.",
          f"- On FUSeg, misses stay rare for everyone: all 18 {pc(mi['fuseg']['groups']['P18_archmean']['est'])}, nnU-Net {pc(mi['fuseg']['per_model']['nnunet_2d']['miss_rate'])}.",
          "- Seed variation of one architecture's AZH miss rate is up to "
          + f"{100 * max(pa[a]['max'] - pa[a]['min'] for a in ARCHS):.1f} percentage points ({short(max(ARCHS, key=lambda a: pa[a]['max'] - pa[a]['min']))}).",
          ""]

    # ---- padding
    pd = R["padding"]
    L += ["## 5. AZH padding analysis with all pretrained models", "",
          "Share of pretrained models that miss an image (Dice < 0.1), over non-empty images, using every individual model: original ten 29 models, new eight 22 models, all 51.", "",
          "| dataset | models | mean miss share | Spearman with black share | Spearman with lesion fraction | majority miss, nnU-Net detects | nnU-Net misses, majority detects |",
          "|---|---|---|---|---|---|---|"]
    for s in ("azh", "azh_train_slice", "fuseg"):
        for gname in ("P10_all_seeds", "N8_all_seeds", "P18_all_seeds"):
            v = pd[s][gname]
            L.append(f"| {NICE[s]} | {gname} ({v['n_models']}) | {v['mean_miss_share']:.3f} | {v['spearman_black_share_vs_miss_share']:+.2f} | {v['spearman_frac_vs_miss_share']:+.2f} | "
                     f"{v['n_majority_miss_nnunet_detect']} | {v['n_nnunet_miss_majority_detect']} |")
    a6 = P6["azh_explanation"]["azh"]
    L += ["", f"V6 (10 seed-0 models) on AZH: Spearman with black share {a6['black_pixel_share']['spearman_with_pretrained_miss_share']:+.2f}, with lesion fraction {a6['frac_spearman_with_pretrained_miss_share']:+.2f}; "
          f"{a6['n_pretrained_majority_miss_nnunet_detect']} images where most pretrained models miss and nnU-Net detects, {a6['n_nnunet_miss_pretrained_majority_detect']} the other way.", "",
          "Within lesion-fraction terciles (AZH, all 51 models), miss share in images with more vs less padding than the tercile median: "
          + "; ".join(f"tercile {t['frac_tercile']} (n {t['n']}): {t['miss_more_padding']:.2f} vs {t['miss_less_padding']:.2f}" for t in pd["azh"]["P18_all_seeds"]["miss_by_frac_tercile_and_padding"])
          + ". New eight only: "
          + "; ".join(f"{t['miss_more_padding']:.2f} vs {t['miss_less_padding']:.2f}" for t in pd["azh"]["N8_all_seeds"]["miss_by_frac_tercile_and_padding"])
          + ". V6 (10 models): " + "; ".join(f"{t['pretrained_miss_more_padding']:.2f} vs {t['pretrained_miss_less_padding']:.2f}" for t in a6["miss_by_frac_tercile_and_padding"]) + ".",
          "- The V6 pattern holds for the new architectures: misses concentrate on heavily padded AZH crops within every lesion-size tercile, and nnU-Net detects those images. This remains correlational (see V6 hypothesis).",
          ""]

    # ---- what changed
    L += ["## What changed from V6", "",
          "- Loader `perimage_v7`; V6 output reproduced exactly before any new analysis (stored under `v6` in the json).",
          "- Candidates: M19 (19), M11s, N8s, P10s and single-seed sets M19_s0..2 added; selection also at amplitude 28; per-synthetic-seed picks; within-0.01/0.02 counts.",
          "- Misses per individual model (51 pretrained + nnU-Net) with unit-bootstrap intervals (the V6 draws), summarised per architecture over seeds. V6 had no miss-rate intervals.",
          "- Padding analysis repeated with all 51 pretrained models; black-pixel share also reported over all kept images and for Medetec and CO2Wounds-V2.",
          f"- Main shifts: with 19 candidates the synthetic pick (nnU-Net) is no longer close to optimal on AZH (loss {s19['synthetic']['amp40']['loss']['azh']:.3f}) because segformer_mitb2 overtakes nnU-Net there; "
          f"mean synthetic-pick loss rises from {S['M']['synthetic']['amp40']['mean_loss']:.3f} to {s19['synthetic']['amp40']['mean_loss']:.3f}, still below random ({s19['random_mean_over_B']:.3f}) and the other-wound chooser ({s19['offdiag_mean']:.3f}). "
          f"The synthetic pick is not stable across training seeds. Every one of the 18 pretrained architectures misses far more AZH wounds than nnU-Net (lowest architecture mean {pc(min(v['mean'] for a, v in mi['azh']['per_architecture'].items() if a != 'nnunet_2d'))} against {pc(mi['azh']['per_model']['nnunet_2d']['miss_rate'])}).",
          "- Not extended: SAM/MedSAM (section 6 of V6 is reproduced unchanged inside `v6`; the new SAM runs are covered elsewhere).",
          "", "## Limitations", "",
          "- Selection losses are point estimates, as in V6; no interval is given because the loss of a pick depends on a maximum over candidates.",
          "- nnU-Net has a single training; its synthetic and clinical scores carry the noise of one training run, while the seed-averaged candidates average over up to three.",
          "- manet_r18 has 2 seeds and manet_r50 only 1 (diverged runs). manet_r50 is FUSeg's best M19 candidate on one training.",
          "- Bootstrap intervals cover image sampling only; models are fixed. Intervals for group means do not include seed-to-seed variation beyond the seeds averaged.",
          "- Medetec has 38 photographs, so its intervals are wide; on CO2Wounds-V2 the two top M19 candidates (segformer_mitb2 and nnU-Net) differ by less than 0.001 Dice, so its 'best' is essentially a tie.",
          ""]
    txt = "\n".join(L)
    assert "\u2014" not in txt and "\u2013" not in txt
    open(os.path.join(OUT, "PRACTICAL_V7.md"), "w").write(txt)


